import SwiftUI
struct ProfileView: View { @EnvironmentObject private var appState: AppState; var body: some View { NavigationStack { Form { Section("User"){TextField("Name",text:$appState.activeResume.name).onSubmit{appState.saveResume()}; Text("Last updated \(appState.activeResume.lastModified.formatted(date:.abbreviated,time:.shortened))").foregroundStyle(DS.ColorToken.textMuted)}; Section("Job workflow"){LabeledContent("Queued",value:"\(appState.queue.count)"); LabeledContent("Starred",value:"\(appState.starred.count)")}; Section("App"){Text("Resume Master iOS"); Text("Minimum deployment target: iOS 17")} }.navigationTitle("Profile").navigationBarTitleDisplayMode(.inline) } } }
